    46→// postBlockProcessConfig is a structure that contains the data needed to
    47→// process the beacon block after validating the state transition function
    48→type postBlockProcessConfig struct {
    49→	ctx            context.Context
    50→	roblock        consensusblocks.ROBlock
    51→	headRoot       [32]byte
    52→	postState      state.BeaconState
    53→	isValidPayload bool
    54→}
    55→
    56→// postBlockProcess is called when a gossip block is received. This function performs
    57→// several duties most importantly informing the engine if head was updated,
    58→// saving the new head information to the blockchain package and
    59→// handling attestations, slashings and similar included in the block.
    60→func (s *Service) postBlockProcess(cfg *postBlockProcessConfig) error {
    61→	ctx, span := trace.StartSpan(cfg.ctx, "blockChain.onBlock")
    62→	defer span.End()
    63→	cfg.ctx = ctx
    64→	if err := consensusblocks.BeaconBlockIsNil(cfg.roblock); err != nil {
    65→		return invalidBlock{error: err}
    66→	}
    67→	startTime := time.Now()
    68→	fcuArgs := &fcuConfig{}
    69→
    70→	if s.inRegularSync() {
    71→		defer s.handleSecondFCUCall(cfg, fcuArgs)
    72→	}
    73→	if features.Get().EnableLightClient && slots.ToEpoch(s.CurrentSlot()) >= params.BeaconConfig().AltairForkEpoch {
    74→		defer s.processLightClientUpdates(cfg)
    75→	}
    76→	defer s.sendStateFeedOnBlock(cfg)
    77→	defer reportProcessingTime(startTime)
    78→	defer reportAttestationInclusion(cfg.roblock.Block())
    79→
    80→	err := s.cfg.ForkChoiceStore.InsertNode(ctx, cfg.postState, cfg.roblock)
    81→	if err != nil {
    82→		// Do not use parent context in the event it deadlined
    83→		ctx = trace.NewContext(context.Background(), span)
    84→		s.rollbackBlock(ctx, cfg.roblock.Root())
    85→		return errors.Wrapf(err, "could not insert block %d to fork choice store", cfg.roblock.Block().Slot())
    86→	}
    87→	if err := s.handleBlockAttestations(ctx, cfg.roblock.Block(), cfg.postState); err != nil {
    88→		return errors.Wrap(err, "could not handle block's attestations")
    89→	}
    90→
    91→	s.InsertSlashingsToForkChoiceStore(ctx, cfg.roblock.Block().Body().AttesterSlashings())
    92→	if cfg.isValidPayload {
    93→		if err := s.cfg.ForkChoiceStore.SetOptimisticToValid(ctx, cfg.roblock.Root()); err != nil {
    94→			return errors.Wrap(err, "could not set optimistic block to valid")
    95→		}
    96→	}
    97→	start := time.Now()
    98→	cfg.headRoot, err = s.cfg.ForkChoiceStore.Head(ctx)
    99→	if err != nil {
   100→		log.WithError(err).Warn("Could not update head")
   101→	}
   102→	newBlockHeadElapsedTime.Observe(float64(time.Since(start).Milliseconds()))
   103→	if cfg.headRoot != cfg.roblock.Root() {
   104→		s.logNonCanonicalBlockReceived(cfg.roblock.Root(), cfg.headRoot)
   105→		return nil
   106→	}
   107→	if err := s.getFCUArgs(cfg, fcuArgs); err != nil {
   108→		log.WithError(err).Error("Could not get forkchoice update argument")
   109→		return nil
   110→	}
   111→	if err := s.sendFCU(cfg, fcuArgs); err != nil {
   112→		return errors.Wrap(err, "could not send FCU to engine")
   113→	}
   114→
   115→	return nil
   116→}
