   118→func getStateVersionAndPayload(st state.BeaconState) (int, interfaces.ExecutionData, error) {
   119→	if st == nil {
   120→		return 0, nil, errors.New("nil state")
   121→	}
   122→	var preStateHeader interfaces.ExecutionData
   123→	var err error
   124→	preStateVersion := st.Version()
   125→	switch preStateVersion {
   126→	case version.Phase0, version.Altair:
   127→	default:
   128→		preStateHeader, err = st.LatestExecutionPayloadHeader()
   129→		if err != nil {
   130→			return 0, nil, err
   131→		}
   132→	}
   133→	return preStateVersion, preStateHeader, nil
   134→}
