   336→func (s *Service) updateEpochBoundaryCaches(ctx context.Context, st state.BeaconState) error {
   337→	e := coreTime.CurrentEpoch(st)
   338→	if err := helpers.UpdateCommitteeCache(ctx, st, e); err != nil {
   339→		return errors.Wrap(err, "could not update committee cache")
   340→	}
   341→	if err := helpers.UpdateProposerIndicesInCache(ctx, st, e); err != nil {
   342→		return errors.Wrap(err, "could not update proposer index cache")
   343→	}
   344→	go func(ep primitives.Epoch) {
   345→		// Use a custom deadline here, since this method runs asynchronously.
   346→		// We ignore the parent method's context and instead create a new one
   347→		// with a custom deadline, therefore using the background context instead.
   348→		slotCtx, cancel := context.WithTimeout(context.Background(), slotDeadline)
   349→		defer cancel()
   350→		if err := helpers.UpdateCommitteeCache(slotCtx, st, ep+1); err != nil {
   351→			log.WithError(err).Warn("Could not update committee cache")
   352→		}
   353→	}(e)
   354→	// The latest block header is from the previous epoch
   355→	r, err := st.LatestBlockHeader().HashTreeRoot()
   356→	if err != nil {
   357→		log.WithError(err).Error("Could not update proposer index state-root map")
   358→		return nil
   359→	}
   360→	// The proposer indices cache takes the target root for the previous
   361→	// epoch as key
   362→	if e > 0 {
   363→		e = e - 1
   364→	}
   365→	target, err := s.cfg.ForkChoiceStore.TargetRootForEpoch(r, e)
   366→	if err != nil {
   367→		log.WithError(err).Error("Could not update proposer index state-root map")
   368→		return nil
   369→	}
   370→	err = helpers.UpdateCachedCheckpointToStateRoot(st, &forkchoicetypes.Checkpoint{Epoch: e, Root: target})
   371→	if err != nil {
   372→		log.WithError(err).Error("Could not update proposer index state-root map")
   373→	}
   374→	return nil
   375→}
