   397→// This feeds in the attestations included in the block to fork choice store. It's allows fork choice store
   398→// to gain information on the most current chain.
   399→func (s *Service) handleBlockAttestations(ctx context.Context, blk interfaces.ReadOnlyBeaconBlock, st state.BeaconState) error {
   400→	// Feed in block's attestations to fork choice store.
   401→	for _, a := range blk.Body().Attestations() {
   402→		committees, err := helpers.AttestationCommitteesFromState(ctx, st, a)
   403→		if err != nil {
   404→			return err
   405→		}
   406→		indices, err := attestation.AttestingIndices(a, committees...)
   407→		if err != nil {
   408→			return err
   409→		}
   410→		r := bytesutil.ToBytes32(a.GetData().BeaconBlockRoot)
   411→		if s.cfg.ForkChoiceStore.HasNode(r) {
   412→			s.cfg.ForkChoiceStore.ProcessAttestation(ctx, indices, r, a.GetData().Target.Epoch)
   413→		} else if features.Get().EnableExperimentalAttestationPool {
   414→			if err = s.cfg.AttestationCache.Add(a); err != nil {
   415→				return err
   416→			}
   417→		} else if err = s.cfg.AttPool.SaveBlockAttestation(a); err != nil {
   418→			return err
   419→		}
   420→	}
   421→	return nil
   422→}
   423→
   424→// InsertSlashingsToForkChoiceStore inserts attester slashing indices to fork choice store.
   425→// To call this function, it's caller's responsibility to ensure the slashing object is valid.
   426→// This function requires a write lock on forkchoice.
   427→func (s *Service) InsertSlashingsToForkChoiceStore(ctx context.Context, slashings []ethpb.AttSlashing) {
   428→	for _, slashing := range slashings {
   429→		indices := blocks.SlashableAttesterIndices(slashing)
   430→		for _, index := range indices {
   431→			s.cfg.ForkChoiceStore.InsertSlashedIndex(ctx, primitives.ValidatorIndex(index))
   432→		}
   433→	}
   434→}
