    23→
    24→// ByVersion returns the BeaconChainConfig that has the given version in its ForkVersionSchedule.
    25→// The configset ensures that each fork version schedule entry uniquely points to a single BeaconChainConfig.
    26→func ByVersion(version [fieldparams.VersionLength]byte) (*BeaconChainConfig, error) {
    27→	return configs.byVersion(version)
    28→}
    29→
    30→// SetActive sets the given config as active (the config that will be returned by GetActive).
    31→// SetActive will always overwrite any config with the same ConfigName before setting the updated value to active.
    32→func SetActive(c *BeaconChainConfig) error {
    33→	return configs.setActive(c)
    34→}
    35→
    36→// SetActiveWithUndo attempts to set the active config, and if successful,
    37→// returns a callback function that can be used to revert the configset back to its previous state.
    38→func SetActiveWithUndo(c *BeaconChainConfig) (func() error, error) {
    39→	return configs.setActiveWithUndo(c)
